def is_plausible_creditor_line(line: str) -> bool:
    line = line.strip()
    if len(line) < 2 or len(line) > 80:
        return False
    if _SKIP_CREDITOR_LINES.match(line):
        return False
    if is_city_state_line(line):
        return False
    if re.match(r"^\d{3}[-\s]?\d{2}[-\s]?\d{4}$", line):
        return False
    # Amount / numeric table rows are not creditor names. Only reject when the
    # leading token really is a bare number or currency amount: creditor names
    # such as "21ST MORTGAGE" or "7-ELEVEN" fuse digits with letters and must
    # not be discarded just because they *start* with a digit.
    first_token = line.split()[0]
    if re.search(r"[\d\$%]", first_token) and not re.search(r"[A-Za-z]", first_token):
        return False
    if line.lower().startswith("http"):
        return False
    return bool(re.search(r"[A-Za-z]", line))

