_UNKNOWN_CREDITOR = frozenset({"unknown", "unknown creditor", "n/a", "na"})


def _canonical_creditor(creditor: str) -> str:
    """Case- and whitespace-insensitive form used for filler tokens and de-duplication."""
    return re.sub(r"\s+", " ", (creditor or "").strip()).casefold()


def is_junk_creditor_name(creditor: str) -> bool:
    name = (creditor or "").strip()
    if not name:
        return True
    if not is_plausible_creditor_line(name):
        return True
    # Bureaus emit these placeholders in any casing ("Unknown", "N/A", ...).
    if _canonical_creditor(name) in _UNKNOWN_CREDITOR:
        return True

